<template>
  <section class="flex flex-col gap-6">
    <SubcontractorCompaniesListHeader>
      <SubcontractorCompaniesListFilters :params="params" />
    </SubcontractorCompaniesListHeader>
    <Card>
      <AppLoader v-if="isLoading" subject="subcontractor companies" variant="inline" />
      <AppError v-else-if="error" :error="error" title="Failed to load subcontractor companies" variant="table" />
      <ResponsiveTable v-else-if="data && data.items.length > 0" rounded>
        <ResponsiveTableHeader>
          <ResponsiveTableHead>Company</ResponsiveTableHead>
          <ResponsiveTableHead>Email</ResponsiveTableHead>
          <ResponsiveTableHead>Phone</ResponsiveTableHead>
          <ResponsiveTableHead>Subcontractor canvassers</ResponsiveTableHead>
          <ResponsiveTableHead>Status</ResponsiveTableHead>
        </ResponsiveTableHeader>
        <ResponsiveTableBody>
          <ResponsiveTableRow
            v-for="company in data.items"
            :key="company.id"
            :to="{ name: 'subcontractor-companies-id', params: { id: company.id } }"
          >
            <ResponsiveTableCell :cols="4" :cols-sm="4" label="Company">
              <div class="flex items-center gap-3">
                <AvatarImageWrapper
                  :src="company.logo_url"
                  :alt="company.name"
                  :fallback="company.name.charAt(0)"
                  size="sm"
                />
                <span class="font-medium line-clamp-1">{{ company.name }}</span>
              </div>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="4" :cols-sm="2" label="Email">
              <span class="text-sm break-all">{{ company.email }}</span>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="4" :cols-sm="2" label="Phone">
              <span class="text-sm">{{ company.phone }}</span>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="4" :cols-sm="2" label="Subcontractor canvassers">
              {{ company.subcanvassers_count }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="4" :cols-sm="2" label="Status">
              <Badge :variant="getSubcontractorCompanyStatus(company.status).variant">
                {{ getSubcontractorCompanyStatus(company.status).label }}
              </Badge>
            </ResponsiveTableCell>
          </ResponsiveTableRow>
        </ResponsiveTableBody>
        <ResponsiveTableFooter :colspan="5" :cols="4" :cols-sm="4">
          <AppPagination
            :page="params.page || 1"
            :size="params.size || 10"
            :total="data.total_count"
            label="companies"
          />
        </ResponsiveTableFooter>
      </ResponsiveTable>
      <AppGuidedEmpty v-else-if="showGuided && guidedContent" v-bind="guidedContent" variant="table" />
      <AppEmpty v-else subject="subcontractor companies" variant="table" />
    </Card>
  </section>
</template>

<script setup lang="ts">
import {
  getSubcontractorCompanyList,
  type GetSubcontractorCompanyListData,
  type GetSubcontractorCompanyListResponse,
  type SortType,
  type SubcontractorCompaniesSortBy,
  type SubcontractorCompanyStatus,
} from '~/client';
import { getSubcontractorCompanyStatus } from '~/constants/subcontractor-companies/statusConfig';
import { subcontractorCompaniesGuidedEmpty } from '~/constants/guidedEmpty/subcontractorCompanies';

definePageMeta({
  roles: ['admin'],
  backLabel: 'subcontractor companies',
});

useHead({
  title: 'Subcontractor Companies',
});

const route = useRoute('subcontractor-companies');

const params = computed((): NonNullable<GetSubcontractorCompanyListData['query']> => {
  const queryParams = {
    ...parsePagination(route.query),
    sort_type: (route.query.sort_type as SortType) || 'asc',
    sort_by: (route.query.sort_by as SubcontractorCompaniesSortBy) || 'name',
    search_query: (route.query.search_query as string) || undefined,
    statuses: processArrayQueryParameterFromUrl<SubcontractorCompanyStatus>(route.query.statuses),
  };

  return Object.fromEntries(Object.entries(queryParams).filter(([_, value]) => value !== undefined)) as NonNullable<
    GetSubcontractorCompanyListData['query']
  >;
});

const { data, error, isLoading } = useQuery({
  key: () => ['subcontractor-companies-list', params.value],
  query: (): Promise<GetSubcontractorCompanyListResponse> =>
    getSubcontractorCompanyList({ composable: '$fetch', query: ref(params.value) }),
  enabled: () => route.name === 'subcontractor-companies',
});

const isEmpty = computed(() => !data.value || data.value.items.length === 0);
const { guidedContent, showGuided } = useGuidedEmpty(subcontractorCompaniesGuidedEmpty, isEmpty);
</script>
